// Bot1ManagementSlippage.mqh
// Bot 1 virtual branch: move the shared virtual level under slippage
// control. Contract: virtual-slippage-contract.md (same folder).
// Buy 0x29c64..0x29de9, sell 0x2d3d1..0x2d55a; ends before the high/low
// level branch. One segment only, not a full management function.
#ifndef BOT1_MANAGEMENT_SLIPPAGE_MQH
#define BOT1_MANAGEMENT_SLIPPAGE_MQH

// Parameter names are reconstructed. Shared values that the original
// reads after a call are passed by reference so every read happens
// where the contract places it. changed is set on success only and is
// never cleared here. No modify/close, digits query or time write.
void Bot1AdvanceSlippageVirtualStop(const bool is_buy,
                                    const string symbol,            // managed symbol
                                    const int enabled,              // int 0x623f0
                                    const bool distance_passed,     // flag from open-price table step
                                    const double &trail_distance,   // 0x62400
                                    const double &start_distance,   // 0x623f8
                                    const double &limit_distance,   // 0x62408
                                    const double &freeze_distance,  // 0x67468
                                    const double &unit,             // 0x66d98
                                    const double &bid,              // latest bid
                                    const double &ask,              // latest ask
                                    const double open_price,        // captured position value
                                    const double take_profit,       // captured position value
                                    const double reference_level,   // table reference, not 0x62410 anchor
                                    double &level,                  // shared virtual level 0x62580
                                    bool &changed)
  {
   if(enabled == 1 && distance_passed && trail_distance > 0.0)
     {
      const double captured_level = level;
      const double captured_price = is_buy ? bid : ask;
      const double point = SymbolInfoDouble(symbol, SYMBOL_POINT);
      // Settings, prices and the level below are read after the point
      // query; bid, ask and level are current values, not the copies.
      const double trail_offset = trail_distance * unit;

      if(is_buy)
        {
         if(captured_level + point + trail_offset < captured_price &&
            reference_level + start_distance * unit < bid &&
            bid < take_profit - freeze_distance &&
            level < unit * limit_distance + open_price)
           {
            Print("Slippage control active");
            // Price, distance and unit are read again after Print.
            const double new_level = bid - trail_distance * unit;
            changed = true;
            level = new_level;
           }
        }
      else
        {
         if(captured_price < (captured_level - point) - trail_offset &&
            ask < reference_level - start_distance * unit &&
            freeze_distance + take_profit < ask &&
            open_price - unit * limit_distance < level)
           {
            // "controle" is the original spelling (string at 0x55d30).
            Print("Slippage controle active");
            // Price, distance and unit are read again after Print.
            const double new_level = trail_distance * unit + ask;
            changed = true;
            level = new_level;
           }
        }
     }
  }

#endif

